CREATE TABLE IF NOT EXISTS studio_services (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, description TEXT, price DECIMAL(12,2) DEFAULT NULL, duration VARCHAR(80), sort_order INT DEFAULT 0, is_published TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS studio_partners (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, logo_url TEXT, website_url TEXT, sort_order INT DEFAULT 0, is_published TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS studio_videos (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, video_url TEXT NOT NULL, poster_url TEXT, sort_order INT DEFAULT 0, is_published TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS studio_faqs (id INT AUTO_INCREMENT PRIMARY KEY, question VARCHAR(255) NOT NULL, answer TEXT NOT NULL, sort_order INT DEFAULT 0, is_published TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS studio_banners (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, subtitle TEXT, image_url TEXT, button_label VARCHAR(100), button_url TEXT, sort_order INT DEFAULT 0, is_published TINYINT DEFAULT 1);
